import{c as a,Q as r,j as e,m as o}from"./chunks/framework.hhGiamYR.js";const h=JSON.parse('{"title":"我为何为一个僭主写传记——关于卡斯特鲁乔，一部\\"不真实\\"的传记背后的真话","description":"马基雅维利唯一一部传记写的是卢卡僭主卡斯特鲁乔·卡斯特拉卡尼。他编造了传主的临终遗言，还把古希腊哲人的妙语安在传主头上——因为他写的不是历史，而是政治。","frontmatter":{"date":"2026-10-05T00:00:00.000Z","title":"我为何为一个僭主写传记——关于卡斯特鲁乔，一部\\"不真实\\"的传记背后的真话","description":"马基雅维利唯一一部传记写的是卢卡僭主卡斯特鲁乔·卡斯特拉卡尼。他编造了传主的临终遗言，还把古希腊哲人的妙语安在传主头上——因为他写的不是历史，而是政治。"},"headers":[],"relativePath":"research/castruccio-castracani/index.md","filePath":"research/castruccio-castracani/index.md"}'),l={name:"research/castruccio-castracani/index.md"};function i(p,t,u,c,n,m){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="我为何为一个僭主写传记——关于卡斯特鲁乔-一部-不真实-的传记背后的真话" tabindex="-1">我为何为一个僭主写传记——关于卡斯特鲁乔，一部&quot;不真实&quot;的传记背后的真话 <a class="header-anchor" href="#我为何为一个僭主写传记——关于卡斯特鲁乔-一部-不真实-的传记背后的真话" aria-label="Permalink to &quot;我为何为一个僭主写传记——关于卡斯特鲁乔，一部&quot;不真实&quot;的传记背后的真话&quot;">​</a></h1><p>我写过急件、史书、喜剧和长诗，但真正算得上&quot;传记&quot;的，只有一部。1520 年，我访问卢卡期间写下了《卢卡人卡斯特鲁乔·卡斯特拉卡尼的生平》，把它题献给扎诺比·布昂德尔蒙蒂和路易吉·阿拉曼尼——奥里切拉里花园里那两个愿意凭才气行动的朋友。</p><p>传主卡斯特鲁乔是十四世纪初卢卡城的领主，佛罗伦萨最可怕的敌人之一。我选他，不是因为敬仰，而是因为在他一生的际遇里，才气与机运的交缠太过典型。开篇我就把话挑明了：</p><blockquote><p>📖 <strong>原文</strong>：《卢卡人卡斯特鲁乔·卡斯特拉卡尼的生平》开篇 &quot;所有那些（至少是大部分）在此世取得伟大业绩并出类拔萃的人都是出身卑微、身世不明，或者至少经历过命运女神所施加的非同寻常的艰辛。……我坚信这是命运女神带来的结果，命运女神想证明给世界看：是她而非智慧女神造就了人类的伟大。&quot;</p><ul><li>全文：[05-《卢卡人卡斯特鲁乔 卡斯特拉卡尼的生平》.md](<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/05-%E3%80%8A%E5%8D%A2%E5%8D%A1%E4%BA%BA%E5%8D%A1%E6%96%AF%E7%89%B9%E9%B2%81%E4%B9%94" target="_blank" rel="noreferrer">https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/05-《卢卡人卡斯特鲁乔</a> 卡斯特拉卡尼的生平》.md)</li></ul></blockquote><p>这句话是整部传记的钥匙。卡斯特鲁乔的来历正合乎此说：一个被弃在葡萄园里的男婴，让迪亚诺拉夫人拾起，由她的教士哥哥安东尼奥收养。安东尼奥一心想把他养成教士，可这孩子十四岁就把教会的书扔在一边，满心都是武器。雇佣兵队长弗朗切斯科·奎尼吉看中了他，收他入门；此后他做帕戈洛·奎尼吉的监护人，借比萨的乌古乔内之手夺取卢卡，最终被拥为全城君主。一个弃婴走到这一步，靠的显然不只是出身。</p><p>然而我在这部传记里动了手脚，而且动得不小。若你逐字细读，会发现两处&quot;不真实&quot;。其一，卡斯特鲁乔临终前对帕戈洛说的那番长篇遗言里，他说自己&quot;不曾娶妻生子&quot;；可我在注释里已经写明，事实上他结过婚，还育有几个子女。其二，传记末尾那一长串机智辛辣的答问，我大都改编自第欧根尼·拉尔修的《名哲言行录》，把它们安到了卡斯特鲁乔头上。这两处破绽不是疏忽。我从来就没打算写一部忠实的历史传记，我要的是借一具历史的躯壳，讲我自己的道理。</p><p>那个道理，就埋在临终遗言的正中。卡斯特鲁乔把一座城邦留给养子帕戈洛，临了嘱咐的却是这么几句：</p><blockquote><p>📖 <strong>原文</strong>：《卢卡人卡斯特鲁乔·卡斯特拉卡尼的生平》临终遗言 &quot;在这个世界上非常重要的事情就是，要有自知之明，能够衡量自己的精神力量和实际力量。如果知道自己没有征战的本领，那么就必须用和平的手段去统治。&quot;</p><ul><li>全文：[05-《卢卡人卡斯特鲁乔 卡斯特拉卡尼的生平》.md](<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/05-%E3%80%8A%E5%8D%A2%E5%8D%A1%E4%BA%BA%E5%8D%A1%E6%96%AF%E7%89%B9%E9%B2%81%E4%B9%94" target="_blank" rel="noreferrer">https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/05-《卢卡人卡斯特鲁乔</a> 卡斯特拉卡尼的生平》.md)</li></ul></blockquote><p>一个靠征战起家的僭主，死前教给继承人的竟是&quot;量力而行&quot;。这话自然不是卡斯特鲁乔说的，它是我借他的口说给君主们听的。开篇我讲&quot;是命运而非智慧造就伟大&quot;，结尾却让传主谆谆告诫&quot;要有自知之明&quot;——这两句之间隔着一个人的一生，也隔着我一生都在咀嚼的那个难题：命运发牌，可牌到了手上，怎么打仍是你自己的事。</p><p>卡斯特鲁乔打得漂亮。1325 年的塞拉瓦莱，他以一万二千人对佛罗伦萨的三万之众，不肯在开阔平原上硬碰，偏要把战场选在两山之间那条窄得只容二十人并排的关隘，又在头一晚派人潜入城堡、杀了中立领主。结果佛罗伦萨的先头骑兵还来不及戴上头盔就撞上了他的步兵，全军被地势击溃，死者逾两万，他自己只折了一千五百七十人。读到此处你便明白，我为什么说&quot;命运造人&quot;——他赢，是因为他在自己那&quot;另一半&quot;上做到了极致。</p><p>我对他的一句为人方式也念念不忘：</p><blockquote><p>📖 <strong>原文</strong>：《卢卡人卡斯特鲁乔·卡斯特拉卡尼的生平》 &quot;任何事情，只要能以欺诈做成，他绝不使用武力，因为他总是说，给你带来声望的是胜利，而不是取得胜利的方式。&quot;</p><ul><li>全文：[05-《卢卡人卡斯特鲁乔 卡斯特拉卡尼的生平》.md](<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/05-%E3%80%8A%E5%8D%A2%E5%8D%A1%E4%BA%BA%E5%8D%A1%E6%96%AF%E7%89%B9%E9%B2%81%E4%B9%94" target="_blank" rel="noreferrer">https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/05-《卢卡人卡斯特鲁乔</a> 卡斯特拉卡尼的生平》.md)</li></ul></blockquote><p>一个共和国的秘书，为什么会费心去为一个僭主立传？因为卡斯特鲁乔是我所能找到的最干净的样本：命运只给了他一副卑贱的出身，其余的一切——从弃婴到君主——都是他用才气一寸寸挣来的。我在他身上演示的，正是我毕生想讲清的那件事：人可以敬畏机运，却不必把整副人生都交到她手里。传记不过是我的又一件武器，和《君主论》一样，只是换了件外衣。</p><p>尼科洛·马基雅维利，圣卡夏诺</p>',14)])])}const q=a(l,[["render",i]]);export{h as __pageData,q as default};
